// Built-in apps that ship with frieren. Each entry is the default export of
// a builtin package's `dist/bundle.js` (generated by `kernelHost()` at build
// time, see packages/app/vite.ts). Adding a builtin: add it as a workspace
// dependency in apps/frieren/package.json, then add `import x from
// '@justfiles/app-frieren-x/bundle'` and append `x` to BUILTINS below.

import type { BuiltinBundle } from '@justfiles/app/runtime'
import paint from '@justfiles/app-paint/bundle'

export const BUILTINS: readonly BuiltinBundle[] = [paint]
